def FG(show=(),shade=None,mark=None):
  g={"type":"plot","axes":False,"X":[-3.2,3.2],"Y":[-0.42,1.12],"w":580,"h":430,"pad":20,"fns":[{"f":"Math.exp(-x*x/2)","a":-3.2,"b":3.2,"c":"#2f55c8"}],"segs":[{"p":[-3.2,0,3.2,0],"c":"#5a6278","w":2}],"pts":[],"txt":[]}
  if shade: a,b=shade; g["poly"]=[{"p":[[a,0]]+[[a+(b-a)*k/40,math.exp(-(a+(b-a)*k/40)**2/2)] for k in range(41)]+[[b,0]],"fill":"#34b27b","op":.35}]
  for i,v in enumerate(V):
    z=-2.5+0.5*i; g["segs"].append({"p":[z,0,z,math.exp(-z*z/2)],"c":"#c9d3ee","w":2})
    if v in show or "all" in show: g["pts"].append({"x":z,"y":0,"r":4,"c":"#c8242f","t":str(v),"fs":19,"an":"middle","dx":0,"dy":26 if i%2==0 else 52})
    else: g["pts"].append({"x":z,"y":0,"r":4,"c":"#8a91a5","t":"?","fs":19,"an":"middle","dx":0,"dy":26 if i%2==0 else 52})
  for i,p in enumerate(PC):
    z=-2.75+0.5*i; h=math.exp(-z*z/2)
    g["txt"].append({"x":z,"y":(h/2 if h>0.45 else h+0.06+(0.07 if i in (0,11) else 0)),"t":p,"fs":15 if h<0.45 else 17,"c":"#16824f"})
  if mark is not None: g["pts"].append({"x":mark[0],"y":0.0,"r":9,"c":"#c8242f"}); g["segs"].append({"p":[mark[0],0,mark[0],0.95],"c":"#c8242f","w":2,"dash":1}); g["txt"].append({"x":mark[0]+1.25,"y":0.98,"t":mark[1],"fs":22,"c":"#c8242f"})
  return g
